class Solution {
    public int numberOfBoomerangs(int[][] points){
        int answer=0;
        for(int[] center:points){
            Map<Long,Integer> counts=new HashMap<>();
            for(int[] point:points){
                long dx=(long)center[0]-point[0],dy=(long)center[1]-point[1],distance=dx*dx+dy*dy;
                int count=counts.getOrDefault(distance,0);
                answer+=2*count;
                counts.put(distance,count+1);
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun numberOfBoomerangs(points:Array<IntArray>):Int{
        var answer=0;
        for(center in points){
            val counts=hashMapOf<Long,Int>();
            for(point in points){
                val dx=center[0].toLong()-point[0];
                val dy=center[1].toLong()-point[1];
                val distance=dx*dx+dy*dy;
                val count=counts[distance]?:0;
                answer+=2*count;
                counts[distance]=count+1
            }
        };
        return answer
    }
}

